import sys

def main():
    R, C = map(int, sys.stdin.read().strip().split())
    path = []
    for r in range(R):
        for c in range(C):
            if r % 2 == 0:
                if c % 2 == 0:
                    path.append('R')
                else:
                    path.append('L')
            else:
                if c % 2 == 0:
                    path.append('L')
                else:
                    path.append('R')
            if c < C - 1:
                path.append('D' if r % 2 == 0 else 'U')
        if r < R - 1:
            path.append('U' if r % 2 == 0 else 'D')
            path.append('R' if r % 2 == 0 else 'L')
    print(''.join(path))

main()
